// Open and locked differentials. Pure: no DOM, no three.js. Units: m, s, N, rad/s.

// Cornering: each driven wheel follows its own circle about the turn centre, so the outer wheel turns faster.
// radius = turn radius at the axle centre (m, + = turning left, Infinity = straight), v = axle-centre speed (m/s).
// diff = half the speed difference: the side gears' speed relative to the carrier, which the spider gears take up.
export function cornerSpeeds({ halfTrack, wheelR }, radius, v) {
  const k = Number.isFinite(radius) ? halfTrack / radius : 0;
  const left = v * (1 - k) / wheelR, right = v * (1 + k) / wheelR;
  return { left, right, carrier: (left + right) / 2, diff: (right - left) / 2 };
}

// Drive force on an axle. Open: both sides always get the same torque, so the wheel with less grip limits both.
// Locked: the axle turns as one shaft and each wheel can push up to its own grip.
// p = { torque (N·m at the axle), wheelR, normal (N per wheel), muL, muR, locked, resist (N needed to move the car) }.
export function traction({ torque, wheelR, normal, muL, muR, locked, resist = 0 }) {
  const gripL = muL * normal, gripR = muR * normal, want = torque / wheelR;
  let fL, fR, spinL, spinR;
  if (locked) {
    const grip = gripL + gripR, f = Math.min(want, grip);
    fL = grip ? f * gripL / grip : 0; fR = f - fL;
    spinL = spinR = want > grip;
  } else {
    const each = Math.min(want / 2, gripL, gripR);
    fL = fR = each;
    spinL = want / 2 > gripL; spinR = want / 2 > gripR;
  }
  const total = fL + fR;
  return { fL, fR, total, spinL, spinR, moves: total > resist };
}

// Sliding-mesh gearbox. Pure: no DOM, no three.js. A constant-mesh pair drives the layshaft; each gear slides a
// main-shaft wheel into mesh with its layshaft partner, and top gear locks the input straight to the main shaft.
// box = { input: [zInput, zLayshaft], gears: [{ name, lay, main } | { name, direct: true }], final, wheelR (m) }.
// Gear index g: 0… into box.gears, or null for neutral. All wheels share one module, so lay + main = zInput + zLayshaft.

export const layRatio = box => box.input[1] / box.input[0];   // the layshaft turns this many times slower than the input

export function ratio(box, g) {
  const s = box.gears[g];
  if (!s) return Infinity;
  return s.direct ? 1 : layRatio(box) * s.main / s.lay;
}

// Road speed (km/h) at engine speed rpm in gear g, through the final drive (chains, on the Simplex).
export function roadSpeed(box, g, rpm) {
  const r = ratio(box, g);
  return Number.isFinite(r) ? rpm / r / box.final * 2 * Math.PI * box.wheelR / 60 * 3.6 : 0;
}

// Road load and top speed. Pure: no DOM, no three.js. SI units: m, s, kg, N, W.
// car = { cd, area (m²), mass (kg), crr (rolling resistance coefficient), eta (driveline efficiency), grip? (max drive force, N) }.
const RHO = 1.2, G = 9.81;

export const drag = (c, v) => 0.5 * RHO * c.cd * c.area * v * v;
export const rolling = c => c.crr * c.mass * G;

// Engine power needed to hold speed v: aerodynamic drag grows with v³, rolling resistance only with v.
export const powerNeeded = (c, v) => (drag(c, v) + rolling(c)) * v / (c.eta ?? 0.88);

// Top speed with engine power P (W): where power needed meets power available. Bisection; powerNeeded is increasing.
export function topSpeed(c, P) {
  let lo = 0, hi = 200;
  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (powerNeeded(c, m) < P) lo = m; else hi = m; }
  return lo;
}

// One time step of a full-power run: drive force P·η / v, capped by tyre grip at low speed.
export function accelerate(c, P, v, dt) {
  const grip = c.grip ?? 0.5 * c.mass * G;
  const drive = Math.min(grip, P * (c.eta ?? 0.88) / Math.max(v, 0.5));
  return Math.max(0, v + (drive - drag(c, v) - rolling(c)) / c.mass * dt);
}

// Pin-jointed space truss, linear elastic. Pure: no DOM, no three.js. Units: mm, N.
import { gauss } from "./linkage.js";

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

// t = { nodes: [[x, y, z]], members: [{ ends: [i, j], EA }], fixed: [{ node, dof: "xyz" }], loads: [{ node, f: [fx, fy, fz] }] }.
// Returns node displacements u (mm) and member forces (N, + = tension). Supports must remove every rigid-body motion.
export function solveTruss({ nodes, members, fixed, loads }) {
  const N = 3 * nodes.length, K = Array.from({ length: N }, () => new Float64Array(N)), F = new Float64Array(N);
  const geo = members.map(m => {
    const d = sub(nodes[m.ends[1]], nodes[m.ends[0]]), L = Math.hypot(...d);
    return { e: d.map(c => c / L), k: m.EA / L };
  });
  members.forEach((m, n) => {
    const [i, j] = m.ends, { e, k } = geo[n];
    for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) {
      const kab = k * e[a] * e[b];
      K[3 * i + a][3 * i + b] += kab; K[3 * j + a][3 * j + b] += kab;
      K[3 * i + a][3 * j + b] -= kab; K[3 * j + a][3 * i + b] -= kab;
    }
  });
  for (const l of loads) for (let a = 0; a < 3; a++) F[3 * l.node + a] += l.f[a];
  for (const s of fixed) for (const c of s.dof) {
    const r = 3 * s.node + "xyz".indexOf(c);
    K[r].fill(0); for (const row of K) row[r] = 0; K[r][r] = 1; F[r] = 0;
  }
  const x = gauss(K.map(row => Array.from(row)), Array.from(F));
  const u = nodes.map((_, i) => [x[3 * i], x[3 * i + 1], x[3 * i + 2]]);
  const forces = members.map((m, n) => geo[n].k * dot(geo[n].e, sub(u[m.ends[1]], u[m.ends[0]])));
  return { u, forces };
}

// Tubular frame from cross-sections. Each station { x, w (half width), z: [floor, sill, top] } has six nodes (left/right ×
// three levels), braced into a rigid ring. Each bay between stations: longitudinals, a diagonal in every side panel and in
// the floor, and optionally in the top. door: "high" keeps the full-height side truss (300 SL); "low" cuts it down to the
// sill, as a conventional door opening would (no top rail, no upper side diagonal).
// node(s, side, level): side 0 = left (+y), 1 = right (−y); level 0 floor, 1 sill, 2 top.
export function tubeFrame(stations, bays, EA) {
  const node = (s, side, level) => s * 6 + side * 3 + level;
  const nodes = stations.flatMap(st => [1, -1].flatMap(sy => st.z.map(z => [st.x, sy * st.w, z])));
  const members = [], add = (i, j, tag) => members.push({ ends: [i, j], EA, tag });
  stations.forEach((_, s) => {
    for (let lv = 0; lv < 3; lv++) add(node(s, 0, lv), node(s, 1, lv), "ring");
    for (const side of [0, 1]) { add(node(s, side, 0), node(s, side, 1), "ring"); add(node(s, side, 1), node(s, side, 2), "ring"); }
    add(node(s, 0, 0), node(s, 1, 1), "ring"); add(node(s, 0, 1), node(s, 1, 2), "ring");
  });
  bays.forEach((b, s) => {
    const low = b.door === "low", tag = b.door ? "door" : "bay";
    for (const side of [0, 1]) {
      for (let lv = 0; lv < 3; lv++) if (!(low && lv === 2)) add(node(s, side, lv), node(s + 1, side, lv), lv === 2 ? `${tag}-top` : tag);
      add(node(s, side, 0), node(s + 1, side, 1), tag);
      if (!low) add(node(s, side, 1), node(s + 1, side, 2), `${tag}-top`);
    }
    add(node(s, 0, 0), node(s + 1, 1, 0), tag);
    if (b.top && !low) add(node(s, 0, 2), node(s + 1, 1, 2), tag);
  });
  return { nodes, members, node };
}

// Torsion test: rear station held, one front corner lifted by F (N); the other front corner rests on a support.
// Returns stiffness (N·m per degree of twist) and the solution for drawing.
export function twistTest(frame, front, rear, F) {
  const { node } = frame;
  const sol = solveTruss({
    ...frame,
    fixed: [{ node: node(rear, 0, 0), dof: "xyz" }, { node: node(rear, 1, 0), dof: "xz" }, { node: node(front, 1, 0), dof: "z" }],
    loads: [{ node: node(front, 0, 0), f: [0, 0, F] }],
  });
  const track = 2 * frame.nodes[node(front, 0, 0)][1];
  const twist = Math.atan2(sol.u[node(front, 0, 0)][2], track) * 180 / Math.PI;
  return { ...sol, twist, stiffness: F * track / 1000 / twist };
}

// Frontal impact into a rigid wall, one mass. Pure: no DOM, no three.js. SI units.
// The front crushes with force F(x) until the car stops; past zone.length the passenger cell itself deforms (intrusion).
// zone = { type: "crumple", force (N), length (m), ramp (m) }: folds at a nearly constant force, the safety-body idea;
//        { type: "stiff", k (N/m), length (m) }: force rises steeply with every millimetre, as in a rigid older body.
const G = 9.81;

export function crushForce(zone, cellK, x) {
  if (x <= zone.length) return zone.type === "stiff" ? zone.k * x : zone.force * Math.min(1, x / zone.ramp);
  const atEnd = zone.type === "stiff" ? zone.k * zone.length : zone.force;
  return atEnd + cellK * (x - zone.length);
}

// Returns time traces (every ms), peak and mean deceleration in g, crush, intrusion into the cell (m) and duration (s).
export function simulateCrash({ mass, v0, zone, cellK }, dt = 2e-5) {
  let x = 0, v = v0, t = 0, peak = 0, next = 0;
  const out = { t: [], x: [], a: [] };
  while (v > 0 && t < 0.5) {
    const a = crushForce(zone, cellK, x) / mass;
    peak = Math.max(peak, a);
    if (t >= next) { out.t.push(t); out.x.push(x); out.a.push(a / G); next += 1e-3; }
    v -= a * dt; x += Math.max(v, 0) * dt; t += dt;
  }
  out.t.push(t); out.x.push(x); out.a.push(0);
  return { ...out, peakG: peak / G, meanG: v0 / t / G, crush: x, intrusion: Math.max(0, x - zone.length), duration: t };
}

// Self-levelling air suspension vs a steel spring, one corner. Pure: no DOM, no three.js. SI units.
// Air spring: gauge pressure on an effective area carries the load; stiffness k = n·p_abs·A²/V rises with the load,
// so the ride frequency stays nearly constant. A steel spring keeps k and sags instead.
const PATM = 101325, G = 9.81;
const hz = (k, m) => Math.sqrt(k / m) / (2 * Math.PI);

// Static values at ride height. a = { area (m²), volume (m³), n (polytropic exponent) }.
export function airStatic(a, mass) {
  const pg = mass * G / a.area, k = (a.n ?? 1.3) * (pg + PATM) * a.area ** 2 / a.volume;
  return { pg, k, f: hz(k, mass) };
}
export const steelStatic = (k, mass, emptyMass) => ({ sag: (mass - emptyMass) * G / k, f: hz(k, mass) });

// Dynamic corner. kind "air": air spring with a levelling valve that adds or vents air while the body is off ride height;
// kind "steel": spring of rate k, preloaded to carry emptyMass at ride height. z = sag below ride height (m), + = lower.
export function createCorner({ kind, air, k, emptyMass, damping, valveRate = 0.25, tol = 0.003 }) {
  const n = air?.n ?? 1.3;
  const s = { z: 0, v: 0, C: 0, valve: "level" };
  if (kind === "air") s.C = (airStatic(air, emptyMass).pg + PATM) * air.volume ** n;   // p·Vⁿ of the air in the spring
  s.step = (mass, dt) => {
    let F;
    if (kind === "air") F = (s.C / (air.volume - air.area * s.z) ** n - PATM) * air.area;
    else F = emptyMass * G + k * s.z;
    s.v += (mass * G - F - damping * s.v) / mass * dt;
    s.z += s.v * dt;
    if (kind === "air") {
      s.valve = s.z > tol ? "filling" : s.z < -tol ? "venting" : "level";
      if (s.valve === "filling") s.C *= 1 + valveRate * dt; else if (s.valve === "venting") s.C *= 1 - valveRate * dt;
    }
    return s;
  };
  s.pressure = () => (kind === "air" ? s.C / (air.volume - air.area * s.z) ** n - PATM : NaN);   // gauge, Pa
  return s;
}

// Wankel rotary engine geometry. Pure: no DOM, no three.js. Units: m, rad.
// g = { e (eccentricity), R (generating radius), b (rotor width), flank (sagitta of each rotor flank, m) }.
// The housing is the two-lobe epitrochoid; the rotor centre orbits the shaft at radius e while the rotor turns at a third
// of shaft speed, which keeps all three apexes on the housing. Chamber k lies between apex k and apex k + 1.
const TAU = 2 * Math.PI;

export const housing = (alpha, { e, R }) => [e * Math.cos(3 * alpha) + R * Math.cos(alpha), e * Math.sin(3 * alpha) + R * Math.sin(alpha)];
export const rotorCentre = (theta, { e }) => [e * Math.cos(theta), e * Math.sin(theta)];
export const apexAngle = (theta, k) => theta / 3 + k * TAU / 3;   // the housing parameter where apex k sits
export const apexes = (theta, g) => [0, 1, 2].map(k => housing(apexAngle(theta, k), g));
export const displacement = ({ e, R, b }) => 3 * Math.sqrt(3) * e * R * b;   // per chamber: V_max − V_min

// Rotor flank from apex k + 1 back to apex k: a circular arc bulging out towards the housing by g.flank.
export function flank(theta, k, g, n = 16) {
  const [p0, p1] = [apexes(theta, g)[k], apexes(theta, g)[(k + 1) % 3]], c = rotorCentre(theta, g);
  const mx = (p0[0] + p1[0]) / 2, my = (p0[1] + p1[1]) / 2, half = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]) / 2;
  let nx = mx - c[0], ny = my - c[1]; const nl = Math.hypot(nx, ny); nx /= nl; ny /= nl;
  const s = g.flank, rho = (half * half + s * s) / (2 * s), ox = mx - nx * (rho - s), oy = my - ny * (rho - s);
  const a1 = Math.atan2(p1[1] - oy, p1[0] - ox), a0 = Math.atan2(p0[1] - oy, p0[0] - ox);
  let span = a0 - a1; span = Math.atan2(Math.sin(span), Math.cos(span));
  return Array.from({ length: n + 1 }, (_, i) => { const a = a1 + span * i / n; return [ox + rho * Math.cos(a), oy + rho * Math.sin(a)]; });
}

// Chamber k outline: housing from apex k to apex k + 1, then the flank back. n housing samples.
export function chamberOutline(theta, k, g, n = 40) {
  const a0 = apexAngle(theta, k), pts = Array.from({ length: n + 1 }, (_, i) => housing(a0 + TAU / 3 * i / n, g));
  return pts.concat(flank(theta, k, g).slice(1, -1));
}

const area = pts => Math.abs(pts.reduce((s, p, i) => { const q = pts[(i + 1) % pts.length]; return s + p[0] * q[1] - q[0] * p[1]; }, 0)) / 2;
export const chamberVolume = (theta, k, g) => area(chamberOutline(theta, k, g)) * g.b;

// Stroke of chamber k, with the ports on the +y side of the housing and the spark plugs at the −y waist:
// growing on the port side = intake, shrinking on the plug side = compression, growing on the plug side = power,
// shrinking on the port side = exhaust. Shaft and rotor turn the same way (+θ).
export function strokeOf(theta, k, g) {
  const dV = chamberVolume(theta + 1e-3, k, g) - chamberVolume(theta - 1e-3, k, g);
  const [p0, p1] = [apexes(theta, g)[k], apexes(theta, g)[(k + 1) % 3]], portSide = p0[1] + p1[1] > 0;
  return dV > 0 ? (portSide ? "Intake" : "Power") : (portSide ? "Exhaust" : "Compression");
}

export function compressionRatio(g, samples = 720) {
  let lo = Infinity, hi = 0;
  for (let i = 0; i < samples; i++) { const v = chamberVolume(i / samples * 3 * TAU, 0, g); lo = Math.min(lo, v); hi = Math.max(hi, v); }
  return { ratio: hi / lo, vmin: lo, vmax: hi };
}

// Engine cooling water as one lump: heat from the engine against heat the radiator passes to the air. Pure: no DOM,
// no three.js. p = { water (kg), ua (W/K at refSpeed), refSpeed (m/s), still (share of ua with no airflow), airT (°C) }.
// Above 100 °C the surplus heat boils water away instead of raising the temperature.
const CP = 4186, LATENT = 2.26e6;

export const uaAt = (p, v) => p.ua * (p.still + (1 - p.still) * Math.sqrt(Math.min(Math.max(v, 0) / p.refSpeed, 2)));
export const steadyTemp = (p, heat, v) => p.airT + heat / uaAt(p, v);

export function createCooling(p) {
  const s = { T: p.airT, boiled: 0, q: 0, boiling: false };
  s.step = (heat, v, dt) => {
    s.q = uaAt(p, v) * (s.T - p.airT);
    const net = heat - s.q;
    s.boiling = s.T >= 100 && net > 0;
    if (s.boiling) s.boiled += net / LATENT * dt; else s.T = Math.min(100, s.T + net / (p.water * CP) * dt);
    return s;
  };
  s.reset = () => { s.T = p.airT; s.boiled = 0; s.q = 0; s.boiling = false; };
  return s;
}

