      for (let k = 0; k < 4; k++) { const b = new THREE.Mesh(new THREE.BoxGeometry(0.01, 0.05, rh * 0.38), stage.tokenMat("--metal")); b.rotation.x = k * Math.PI / 2; b.position.set(0, 0, 0); b.geometry.translate(0, 0, rh * 0.19); fan.add(b); }
