      ui.set("front", (zF * 1000).toFixed(0)); ui.set("rear", (zR * 1000).toFixed(0));
      ui.set("bar", mode === "air" ? (sims.air.rear.pressure() / 1e5).toFixed(2) : "–");
      ui.set("hz", rideHz("rear").toFixed(2)); ui.set("pitch", (-Math.asin(sin) * 180 / Math.PI).toFixed(2));
    },
  };
}

