    { key: [["--l1", "power"], ["--metal", "exhaust"], ["--l4", "intake"], ["--l2", "compression"]] },
    { readouts: [{ id: "shaft", label: "Eccentric shaft", unit: "deg" }, { id: "rot", label: "Rotor 1", unit: "deg, a third as fast" },
