// A full-power run against the air: engine power against aerodynamic drag (½ρ·cd·A·v²: the power for it grows with v³)
// and rolling resistance. The chart plots power needed over speed for each body; where it meets the engine's power is the
// top speed. Wind streaks and two arrows (drag at the nose, drive at the wheels) show the forces during the run.
// Params (mm, ground at z = 0): label, shapes [{ id, label, cd, area (m²), mass (kg), crr, eta, ps, quoted? (km/h) }],
// power { min, max } (PS), vmax (km/h, chart), nose [x, z], wheel [x, z], wind { x0, x1, y, z0, z1 }, time (× real).
import * as THREE from "three";
import { V, particles } from "../lib/scene/helpers.js";
import { drag, rolling, powerNeeded, topSpeed, accelerate } from "../lib/model/aero.js";

const PS = 735.5, NS = "http://www.w3.org/2000/svg";

export function create(ctx, p) {
4:// Params (mm, ground at z = 0): label, shapes [{ id, label, cd, area (m²), mass (kg), crr, eta, ps, quoted? (km/h) }],
15:  const W = p.wind, wx0 = m(W.x0), wx1 = m(W.x1);
25:  dragA.position.set(m(p.nose[0]) + 0.05, 0, m(p.nose[1])); dragA.rotation.z = Math.PI;   // points backwards from the nose
26:  driveA.position.set(m(p.wheel[0]), 0, m(p.wheel[1]));
3:// mode "grip": one wheel on a slippery patch; open, it spins and the car stays put; locked, both wheels pull.
4:// Params (mm, ground at z = 0): label, mode, halfTrack, wheelR, axleX, wheel "wire" | "tyre", tyreW?, ringR,
6:// corner? { kmh, minRadius (m) }, grip? { torque (N·m at the axle), normal (N per wheel), muLow, muHigh, resist (N),
16:  const h = m(p.halfTrack), R = m(p.wheelR), ax = m(p.axleX);
68:  // Ground: wheel paths in a corner, slippery patch for the grip demo.
72:  stage.bind(patch.material.color, "--l4"); patch.position.set(ax, h, 0.004); patch.visible = p.mode === "grip"; group.add(patch);
86:        ...(p.grip.locks ? [{ id: "lock", label: "Differential lock", pressed: false, onClick: () => setLock(true) }] : [])] },
87:      { readouts: [{ id: "fL", label: `Left wheel, on ${p.grip.surface}`, unit: "N of push" }, { id: "fR", label: "Right wheel, dry", unit: "N of push" },
88:        { id: "total", label: "Total drive", unit: `N, needs ${p.grip.resist} to move` }, { id: "spin", label: "Left wheel", unit: "rpm" }] },
90:      { key: [["--l4", `${p.grip.surface} under the left wheel`]] },
92:  function setLock(v) { locked = v; ui.toggle("open").set(!v); if (p.grip.locks) ui.toggle("lock").set(v); }
98:    const s = cornerSpeeds({ halfTrack: h, wheelR: R }, radius, v);

