      { pts: [[-1700, 1200], [-1750, 2350], [-3650, 2350], [-3750, 1200]], y: [-800, 800] },                                                     // glass superstructure
      { torus: { R: 260, r: 100, pos: [0, 712, 360], rot: [90, 0, 0] }, mirror: true },
    ],
