// Front steering seen from above: Benz's double-pivot (stub-axle) trapezoid against the older centre-pivot turntable axle,
// with each front wheel's axis drawn out to the rear-axle line (where they meet = the turning centre).
// Params (mm, deg): label, kingpinHalf, arm, wheelbase, frontR, rearR, halfTrackRear, stub (kingpin → wheel centre),
// maxSteer. Vehicle frame: rear axle at x = 0, front axle at x = wheelbase.
import * as THREE from "three";
import { V, mat, rod, place, ball, spokedWheel } from "../lib/scene/helpers.js";
import { createDoublePivot, centrePivot } from "../lib/model/steering.js";

const D = Math.PI / 180, FAR = 40;   // m: axis lines longer than this are not drawn (nearly straight ahead)

export function create(ctx, p) {
  const { stage, carRoot } = ctx;
39:  // Axis lines on the ground to the rear-axle line, and the turning centre(s) where they land.
47:  const G = 0.01;   // line height above the ground
99:    layout({ active }) { group.visible = active; },

  return {
    layout({ active, onPhoto }) {
      group.visible = active; road.world.visible = active && !onPhoto;
      tyreMat.opacity = onPhoto ? 0 : 0.5;
      spokeMat.opacity = onPhoto ? 0 : 0.8; spokeMat.userData.solid.visible = !onPhoto;
    },
    update(dt, { onPhoto }) {
      let travel, load = null;
      if (onPhoto) {
        if (playing) photoT += dt;
        travel = Math.sin(photoT * 1.4) * 60;   // car at rest in the photo: just cycle the wheel
      } else {
        if (playing) ride.step(dt * SLOWMO);
        travel = Math.max(-80, Math.min(80, ride.travelMm(p.axle)));
        load = ride.loadPct(p.axle);
        carRoot.position.set(0, 0, ride.bodyZ()); carRoot.rotation.set(0, ride.pitch(), 0);
        road.update(ride);
        if (playing) { trace.push(ride.t, [travel, load]); if (++frameN % 2 === 0) trace.draw(ride.t); }
      }
      const a = pose(travel), vals = { ...a, travel };
6:// el: the .stage element (keeps the photo's aspect). car: the car config (photo, orbit, sun).
