cd /private/tmp/claude-501/-Users-kunabel-workspace-MercedesExperience/5d159ce6-986e-402a-8497-3efb23b3fb41/scratchpad && mkdir -p dl && cat > dl.mjs <<'EOF'
// node dl.mjs <outDir> <slug> "<search text unique to one file title>" → saves <outDir>/<slug>.jpg (1200 px wide) + meta line
import { writeFileSync } from "node:fs";
const [out, slug, needle] = process.argv.slice(2), api = "https://commons.wikimedia.org/w/api.php?format=json&";
const ua = { headers: { "User-Agent": "MuseumTourPhotoSearch/1.0" } };
async function get(url) { for (let i = 0; i < 6; i++) { const t = await (await fetch(url, ua)).text(); try { return JSON.parse(t); } catch { await new Promise(r => setTimeout(r, 4000 * 2 ** i)); } } throw new Error("rate limited"); }
const s = await get(api + `action=query&list=search&srnamespace=6&srlimit=5&srsearch=${encodeURIComponent(needle)}`);
const title = s.query.search.map(r => r.title).find(t => t.includes(needle.split(" ").pop())) ?? s.query.search[0]?.title;
const ii = await get(api + `action=query&prop=imageinfo&iiprop=url|extmetadata|size&iiurlwidth=1200&titles=${encodeURIComponent(title)}`);
const i = Object.values(ii.query.pages)[0].imageinfo[0], m = i.extmetadata, strip = v => (v?.value ?? "").replace(/<[^>]+>/g, "").trim();
const img = Buffer.from(await (await fetch(i.thumburl, ua)).arrayBuffer());
writeFileSync(`${out}/${slug}.jpg`, img);
