// node grid.mjs <image> <out.png> [fit.json] [cam.json]
// Renders the image with a labelled pixel grid (every 50 px, numbers every 100 px). With a fit file, also draws each
// correspondence (red ring = marked pixel) and, with a camera ({ c, yaw, pitch, roll, f }), where the camera projects it
// (green cross), so a bad point stands out.
import { createRequire } from "node:module";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, basename, resolve } from "node:path";
const { chromium } = createRequire("/Users/kunabel/workspace/MercedesExperience/package.json")("playwright");
const [imgPath, out, fitPath, camPath] = process.argv.slice(2);
const fit = fitPath ? JSON.parse(readFileSync(fitPath, "utf8")) : null, cam = camPath ? JSON.parse(readFileSync(camPath, "utf8")) : null;

function project(c, X, W, H) {
  const { yaw, pitch, roll, f } = c, fw = [Math.cos(pitch) * Math.cos(yaw), Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch)];
  let r = [fw[1], -fw[0], 0]; const n = Math.hypot(...r); r = r.map(v => v / n);
  const u = [r[1] * fw[2] - r[2] * fw[1], r[2] * fw[0] - r[0] * fw[2], r[0] * fw[1] - r[1] * fw[0]];
  const cs = Math.cos(roll), sn = Math.sin(roll), R = r.map((v, i) => cs * v + sn * u[i]), U = u.map((v, i) => cs * v - sn * r[i]);
  const d = X.map((v, i) => v - c.c[i]), dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2], z = dot(d, fw);
  return [W / 2 + f * dot(d, R) / z, H / 2 - f * dot(d, U) / z];
}

const browser = await chromium.launch(), page = await browser.newPage();
const html = resolve(dirname(out), `.${basename(out)}.html`);
writeFileSync(html, `<!doctype html><body style="margin:0"><img id=i src="file://${resolve(imgPath)}">`);
await page.goto(`file://${html}`);
const { W, H } = await page.evaluate(async () => { const i = document.getElementById("i"); await i.decode(); return { W: i.naturalWidth, H: i.naturalHeight }; });
await page.setViewportSize({ width: W, height: H });
const marks = [];
for (let x = 50; x < W; x += 50) marks.push(`<line x1=${x} y1=0 x2=${x} y2=${H} stroke="${x % 100 ? "#ff0" : "#0ff"}" stroke-opacity=".${x % 100 ? 35 : 6}" />`);
for (let y = 50; y < H; y += 50) marks.push(`<line x1=0 y1=${y} x2=${W} y2=${y} stroke="${y % 100 ? "#ff0" : "#0ff"}" stroke-opacity=".${y % 100 ? 35 : 6}" />`);
const label = (x, y, t, c = "#0ff") => `<text x=${x} y=${y} fill="${c}" stroke="#000" stroke-width="3" paint-order="stroke" font: font-size="14" font-family="monospace">${t}</text>`;
for (let x = 100; x < W; x += 100) for (let y = 100; y < H; y += 200) marks.push(label(x + 2, y - 3, x));
for (let y = 100; y < H; y += 100) for (let x = 0; x < W; x += 300) marks.push(label(x + 2, y - 3, y, "#ff0"));
for (const [k, q] of (fit?.points ?? []).entries()) {
  marks.push(`<circle cx=${q.px[0]} cy=${q.px[1]} r=7 fill=none stroke="#f20" stroke-width=2.5 />`, label(q.px[0] + 9, q.px[1] + 5, k, "#f60"));
  if (cam) { const [u, v] = project(cam, q.X, W, H); marks.push(`<path d="M${u - 8} ${v}h16M${u} ${v - 8}v16" stroke="#0f0" stroke-width=2.5 />`); }
}
await page.evaluate(svg => document.body.insertAdjacentHTML("beforeend", svg),
  `<svg style="position:absolute;left:0;top:0" width=${W} height=${H}>${marks.join("")}</svg>`);
await page.screenshot({ path: out });
await browser.close();
console.log(`${W}x${H} → ${out}`);

