import { execFileSync } from "node:child_process";
const [S, ...slugs] = process.argv.slice(2);
const alts = JSON.parse(readFileSync(`${S}/alts.json`, "utf8"));
const meta = Object.fromEntries(readFileSync(`${S}/meta.jsonl`, "utf8").split("\n").filter(l => l.startsWith("{")).map(l => [JSON.parse(l).slug, JSON.parse(l)]));
