import { webkit, devices } from "playwright";
const slugs = process.argv.slice(2), out = "/private/tmp/claude-501/-Users-kunabel-workspace-MercedesExperience/5d159ce6-986e-402a-8497-3efb23b3fb41/scratchpad/";
const browser = await webkit.launch();
const ctx = await browser.newContext({ ...devices["iPad Pro 11 landscape"] });
for (const slug of slugs) {
  const page = await ctx.newPage(), errs = [];
  page.on("pageerror", e => errs.push("pageerror: " + e.message)); page.on("console", m => m.type() === "error" && errs.push("console: " + m.text()));
  await page.goto(`http://localhost:8799/stop.html?s=${slug}&debug`);
  try { await page.waitForFunction(() => window.__tour?.stats.frames > 10, null, { timeout: 15000 }); } catch { errs.push("no frames"); }
  const car = (await import(`/Users/kunabel/workspace/MercedesExperience/stops/${slug}/car.js`)).default;
  for (const [i, c] of car.components.entries()) {
    if (car.components.length > 1) await page.getByRole("button", { name: c.label, exact: true }).click().catch(e => errs.push("click " + c.label + ": " + e.message.split("\n")[0]));
    await page.waitForTimeout(2500);
    await page.screenshot({ path: `${out}${slug}-${c.id}.png` });
  }
  console.log(slug, errs.length ? errs.join(" | ") : "ok");
  await page.close();
}
await browser.close();

