// node bp.mjs <slug> <plane: y=700 | x=0 | z=0> u,v [u,v ...]
// Back-projects photo pixels through the camera in stops/<slug>/car.js onto a plane; prints mm, rounded to 10.
const [slug, plane, ...pts] = process.argv.slice(2);
const car = (await import(`/Users/kunabel/workspace/MercedesExperience/stops/${slug}/car.js?${Date.now()}`)).default;
const { c, yaw, pitch, roll, f } = car.photo.cam, W = car.photo.w, H = car.photo.h;
const fw = [Math.cos(pitch) * Math.cos(yaw), Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch)];
let r = [fw[1], -fw[0], 0]; const n = Math.hypot(...r); r = r.map(v => v / n);
const u0 = [r[1] * fw[2] - r[2] * fw[1], r[2] * fw[0] - r[0] * fw[2], r[0] * fw[1] - r[1] * fw[0]];
const cs = Math.cos(roll), sn = Math.sin(roll), R = r.map((v, i) => cs * v + sn * u0[i]), U = u0.map((v, i) => cs * v - sn * r[i]);
const [axis, val] = plane.split("="), k = "xyz".indexOf(axis), q = Number(val);
const out = [];
for (const s of pts) {
  const [u, v] = s.split(",").map(Number), a = (u - W / 2) / f, b = -(v - H / 2) / f;
  const d = fw.map((w, i) => w + a * R[i] + b * U[i]), t = (q - c[k]) / d[k];
  const X = c.map((ci, i) => Math.round((ci + t * d[i]) / 10) * 10);
  out.push(axis === "y" ? `[${X[0]}, ${X[2]}]` : `[${X.join(", ")}]`);
}
console.log(out.join(", "));

